module SafeCaller
  def self.call(callable, *args, default:)
    if callable.respond_to?(:lambda?) && callable.lambda?
      return default unless lambda_accepts_args?(callable, args.size)
    end

    callable.call(*args)
  end

  def self.lambda_accepts_args?(lambda, argc)
    positional = lambda.parameters.select { |type, _| [:req, :opt, :rest].include?(type) }
    required   = positional.count { |type, _| type == :req }
    optional   = positional.count { |type, _| type == :opt }
    has_rest   = positional.any? { |type, _| type == :rest }

    return false if argc < required
    return true  if has_rest

    argc <= required + optional
  end

  private_class_method :lambda_accepts_args?
end
```

