class Proxy < BasicObject
  def initialize(target)
    @target = target
  end

  # Returns true if either the Proxy itself defines the method or the target does.
  def respond_to?(name, include_private = false)
    proxy_methods = [
      :respond_to?, :method, :method_missing, :initialize,
      :==, :!=, :__id__, :equal?, :__send__, :to_s, :inspect
    ]
    if proxy_methods.include?(name)
      true
    else
      @target.respond_to?(name, include_private)
    end
  end

  # Returns a callable that behaves exactly like calling the method on the proxy.
  def method(name)
    if respond_to?(name)
      ->(*args, **kwargs, &block) { self.__send__(name, *args, **kwargs, &block) }
    else
      ::Kernel.raise ::NameError, "undefined method `#{name}' for class `#{self.class}'"
    end
  end

  # Forwards any method call to the target if the target responds to it.
  def method_missing(name, *args, **kwargs, &block)
    if @target.respond_to?(name)
      @target.__send__(name, *args, **kwargs, &block)
    else
      super
    end
  end

  # Delegates equality checks to the target.
  def ==(other)
    @target == other
  end

  def !=(other)
    @target != other
  end

  # Delegates basic identity methods to the target.
  def __id__
    @target.__id__
  end

  def equal?(other)
    @target.equal?(other)
  end

  # Delegates string representations to the target.
  def to_s
    @target.to_s
  end

  def inspect
    @target.inspect
  end
end
