  # Returns a Method object for a method name the target responds to,
  # raising NameError otherwise.
  def method(method_name)
    # If the target responds to this method and it is not already defined
    # on the proxy itself (e.g. :respond_to?), define it dynamically.
    if @target.respond_to?(method_name) && !self.methods.include?(method_name)
      define_singleton_method(method_name) do |*args, &block|
        @target.send(method_name, *args, &block)
