```ruby
class Interval
  def initialize(start, finish)
    @start = start
    @finish = finish
  end

  def overlaps?(other)
    @start <= other.to_a[1] && other.to_a[0] <= @finish
  end

  def to_a
    [@start, @finish]
  end
end
```

